104	    /**
105	     * Rejects an owner payload that is missing or blank in any required field, listing the name of
106	     * each offending field so the caller receives a 400 with a populated {@code errors} array.
107	     */
108	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
109	        List<String> missing = new ArrayList<>();
110	        if (isBlank(ownerFieldsDto.getFirstName())) {
111	            missing.add("firstName");
112	        }
113	        if (isBlank(ownerFieldsDto.getLastName())) {
114	            missing.add("lastName");
115	        }
116	        if (isBlank(ownerFieldsDto.getAddress())) {
117	            missing.add("address");
118	        }
119	        if (isBlank(ownerFieldsDto.getCity())) {
120	            missing.add("city");
121	        }
122	        if (isBlank(ownerFieldsDto.getTelephone())) {
123	            missing.add("telephone");
124	        }
125	        if (!missing.isEmpty()) {
126	            throw new RequiredFieldsMissingException(missing);
127	        }
128	    }
129	
130	    private static boolean isBlank(String value) {
131	        return value == null || value.isBlank();
132	    }
133	
134	    /**
135	     * Normalizes a telephone on create by removing every non-digit character and requiring the
136	     * result to be exactly 10 digits. Returns the 10-digit value to be stored and returned.
137	     *
138	     * @param telephone the raw telephone as supplied by the caller
139	     * @return the normalized 10-digit telephone
140	     * @throws InvalidTelephoneException if the stripped value is not exactly 10 digits
141	     */
142	    private static String normalizeTelephone(String telephone) {
143	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
144	        if (digits.length() != 10) {
145	            throw new InvalidTelephoneException(
146	                "Telephone must contain exactly 10 digits after removing non-digit characters");
147	        }
148	        return digits;
149	    }
