151	    /**
152	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
153	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
154	     *
155	     * @param email the raw email as supplied by the caller, may be {@code null}
156	     * @return the lower-cased email, or {@code null} when none was supplied
157	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
158	     */
159	    private static String normalizeEmail(String email) {
160	        if (email == null || email.isBlank()) {
161	            return null;
162	        }
163	        String trimmed = email.trim();
164	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
165	            throw new InvalidEmailException("Email must be a syntactically valid address");
166	        }
167	        return trimmed.toLowerCase(Locale.ROOT);
168	    }
