170	    /**
171	     * Rejects a create whose normalized telephone is already used by any existing owner, so that
172	     * telephones stay unique across owners. Telephones are normalized to their 10-digit form on
173	     * create, so a direct equality comparison against the stored values is sufficient.
174	     *
175	     * @param normalizedTelephone the normalized 10-digit telephone of the owner being created
176	     * @throws DuplicateTelephoneException if another owner already uses this telephone
177	     */
178	    private void rejectDuplicateTelephone(String normalizedTelephone) {
179	        boolean inUse = this.clinicService.findAllOwners().stream()
180	            .anyMatch(existing -> normalizedTelephone.equals(existing.getTelephone()));
181	        if (inUse) {
